def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    # Start with cwd if path is relative, otherwise start with root
    if path.startswith('/'):
        current = ''  # Represents '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0

    while remaining or current == '':
        # Get next component
        if not remaining:
            break

        parts = remaining.split('/', 1)
        component = parts[0]
        remaining = parts[1] if len(parts) > 1 else ''

        # Skip empty components and '.'
        if not component or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current == '':
                # Already at root, stay at root
                continue
            # Move to parent
            last_slash = current.rfind('/')
            if last_slash == -1:
                current = ''
            else:
                current = current[:last_slash]
            continue

        # Append component
        if current == '':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if it's a symlink
        if candidate in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[candidate]

            # Resolve target
            if target.startswith('/'):
                # Absolute target
                current = ''
                remaining = target[1:] + ('/' + remaining if remaining else '')
            else:
                # Relative target - relative to directory containing the link
                # The link is at candidate, so its directory is current (if candidate = current/component)
                link_dir = current
                remaining = target + ('/' + remaining if remaining else '')
                current = link_dir
        else:
            current = candidate

    # Return the result
    if current == '':
        return '/'
    else:
        return current

